1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	
10	/**
11	 * The single derived key that consolidates all duplicate detection for
12	 * {@code POST /api/owners}. An owner's {@code identityKey} is the lower-case hex SHA-256 of
13	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}; a create is a duplicate
14	 * — and rejected with 409 — only when a new owner's WHOLE identityKey equals an existing owner's.
15	 * Because the telephone is part of the key, two owners with the same surname and postcode but
16	 * different telephones have different keys and are both allowed (the later one is flagged a soft
17	 * match instead — see {@link AssignPossibleDuplicate}); only an exact full-key match collides.
18	 *
19	 * <p>Each component is normalized to the same canonical form the owner is stored with, so a
20	 * request and the owner it would duplicate produce identical keys regardless of input format:
21	 * the telephone to E.164 (see {@link TelephoneE164}), the email trimmed and lower-cased, and the
22	 * surname reduced to its {@link Soundex} code so phonetically-identical surnames share the key.
23	 */
24	public final class OwnerIdentityKey {
25	
26	    private OwnerIdentityKey() {
27	    }
28	
29	    /** The identityKey a create request would have once its owner is built. */
30	    public static String forRequest(OwnerFieldsDto request) {
31	        return of(request.getTelephone(), request.getEmail(), request.getLastName());
32	    }
33	
34	    /** The identityKey of an already-stored owner. */
35	    public static String forOwner(Owner owner) {
36	        return of(owner.getTelephone(), owner.getEmail(), owner.getLastName());
37	    }
38	
39	    private static String of(String telephone, String email, String lastName) {
40	        String raw = normalizeTelephone(telephone) + "|" + normalizeEmail(email) + "|"
41	                + Soundex.encode(lastName);
42	        return sha256Hex(raw);
43	    }
44	
45	    private static String normalizeTelephone(String telephone) {
46	        String e164 = TelephoneE164.toE164(telephone);
47	        return e164 != null ? e164 : (telephone == null ? "" : telephone);
48	    }
49	
50	    private static String normalizeEmail(String email) {
51	        if (email == null || email.isBlank()) {
52	            return "";
53	        }
54	        return email.trim().toLowerCase();
55	    }
56	
57	    private static String sha256Hex(String value) {
58	        try {
59	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
60	            StringBuilder sb = new StringBuilder(digest.length * 2);
61	            for (byte b : digest) {
62	                sb.append(String.format("%02x", b));
63	            }
64	            return sb.toString();
65	        }
66	        catch (NoSuchAlgorithmException e) {
67	            throw new IllegalStateException("SHA-256 not available", e);
68	        }
69	    }
70	}
