1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Fiscal-year arithmetic for owner date-derived values. The fiscal year starts on 1 July and is
10	 * named by the calendar year in which it ends (1 July 2025 to 30 June 2026 is {@code FY26}), so a
11	 * date in July to December belongs to the following calendar year's fiscal year.
12	 *
13	 * <p>Used for the {@code fiscalYear} field, the membership number's year segment and the
14	 * fiscal-year tenure count, so every fiscal-year-derived value stays consistent.
15	 */
16	public final class FiscalYear {
17	
18	    private FiscalYear() {
19	    }
20	
21	    /** First month of the fiscal year. */
22	    public static final Month START = Month.JULY;
23	
24	    /** The calendar year in which the fiscal year containing {@code date} ends. */
25	    public static int endingYear(LocalDate date) {
26	        return date.getMonthValue() >= START.getValue() ? date.getYear() + 1 : date.getYear();
27	    }
28	
29	    /** The last two digits of the fiscal year, zero-padded (e.g. {@code "26"}). */
30	    public static String twoDigit(LocalDate date) {
31	        return String.format("%02d", Math.floorMod(endingYear(date), 100));
32	    }
33	
34	    /** The fiscal year label, {@code 'FY<YY>'} (e.g. {@code "FY26"}). */
35	    public static String label(LocalDate date) {
36	        return "FY" + twoDigit(date);
37	    }
38	
39	    /** Whole fiscal years elapsed from {@code from} to {@code to} (0 when both fall in one fiscal year). */
40	    public static int elapsed(LocalDate from, LocalDate to) {
41	        return endingYear(to) - endingYear(from);
42	    }
43	
44	    /** The owner's fiscal year, derived from its (business-day-adjusted) registration date. */
45	    public static String forOwner(Owner owner) {
46	        return label(owner.getRegistrationDate());
47	    }
48	}
