1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.slf4j.Logger;
6	import org.slf4j.LoggerFactory;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.model.Owner;
10	
11	/**
12	 * Step of {@code POST /api/owners} that records a successful create on the dedicated {@code AUDIT}
13	 * logger. Runs after {@link SaveOwner} so the owner has its persisted id, and emits two things:
14	 * <ul>
15	 * <li>a human-readable audit line carrying the owner id, the assigned {@code customerCode}, the
16	 * effective {@code registrationDate}, the assigned {@code membershipLevel} and the derived
17	 * {@code membershipNumber}; and</li>
18	 * <li>an immutable structured {@link OwnerCreatedEvent} rendered as JSON, stamped with a
19	 * process-wide {@code seq} that increases monotonically across every create.</li>
20	 * </ul>
21	 */
22	public class AuditOwnerCreated {
23	
24	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
25	
26	    /** Monotonically increasing sequence stamped onto each structured event, across all creates. */
27	    private static final AtomicLong SEQUENCE = new AtomicLong();
28	
29	    public void service(@Val Owner owner) {
30	        String membershipNumber = owner.getCustomerCode() + "-M"
31	                + FiscalYear.twoDigit(owner.getRegistrationDate());
32	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} "
33	                        + "membershipNumber={}",
34	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
35	                owner.getMembershipLevel(), membershipNumber);
36	
37	        OwnerCreatedEvent event = OwnerCreatedEvent.forOwner(SEQUENCE.incrementAndGet(), owner);
38	        AUDIT.info(event.toJson());
39	    }
40	}
