1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Immutable structured audit event emitted alongside the human-readable audit line when an owner is
7	 * created. Rendered as the JSON object
8	 * {@code {seq, ownerId, customerCode, membershipLevel, event:"OWNER_CREATED"}}.
9	 *
10	 * <p>{@code customerCode} carries the owner's <em>current primary identifier</em>. Today that is the
11	 * {@link Owner#getCustomerCode() customerCode}; when the customerCode is later unified into a
12	 * {@code memberId}, only {@link #forOwner(long, Owner)} changes so the same field carries the
13	 * memberId instead — the event's shape and the way callers read the identifier stay the same.
14	 *
15	 * <p>Instances are immutable: fields are captured at construction and never mutated, so a recorded
16	 * event cannot be altered after the fact.
17	 */
18	public record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
19	        Integer membershipLevel) {
20	
21	    /** Event marker carried in the {@code event} field. */
22	    public static final String EVENT = "OWNER_CREATED";
23	
24	    /**
25	     * Builds the event for a persisted owner, reading its current primary identifier. This single
26	     * line is the switch point: replace {@code owner.getCustomerCode()} with the memberId once the
27	     * identifiers are unified and every emitted event follows.
28	     */
29	    public static OwnerCreatedEvent forOwner(long seq, Owner owner) {
30	        return new OwnerCreatedEvent(seq, owner.getId(), owner.getCustomerCode(),
31	                owner.getMembershipLevel());
32	    }
33	
34	    /** Canonical JSON rendering of this event. */
35	    public String toJson() {
36	        StringBuilder json = new StringBuilder(96);
37	        json.append("{\"seq\":").append(this.seq)
38	                .append(",\"ownerId\":").append(this.ownerId)
39	                .append(",\"customerCode\":").append(quote(this.customerCode))
40	                .append(",\"membershipLevel\":").append(this.membershipLevel)
41	                .append(",\"event\":").append(quote(EVENT))
42	                .append('}');
43	        return json.toString();
44	    }
45	
46	    private static String quote(String value) {
47	        if (value == null) {
48	            return "null";
49	        }
50	        StringBuilder out = new StringBuilder(value.length() + 2);
51	        out.append('"');
52	        for (int i = 0; i < value.length(); i++) {
53	            char c = value.charAt(i);
54	            switch (c) {
55	                case '"' -> out.append("\\\"");
56	                case '\\' -> out.append("\\\\");
57	                case '\n' -> out.append("\\n");
58	                case '\r' -> out.append("\\r");
59	                case '\t' -> out.append("\\t");
60	                default -> {
61	                    if (c < 0x20) {
62	                        out.append(String.format("\\u%04x", (int) c));
63	                    }
64	                    else {
65	                        out.append(c);
66	                    }
67	                }
68	            }
69	        }
70	        out.append('"');
71	        return out.toString();
72	    }
73	}
