9	/**
10	 * Step of {@code POST /api/owners} that consolidates duplicate detection into the single
11	 * {@link OwnerIdentityKey}. Runs after {@link RequireOwnerFields} has normalized the body (and
12	 * already applied the disposable email-domain blocklist) and rejects the create with 409 when the
13	 * new owner's WHOLE identityKey — the SHA-256 hex of
14	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} — equals an existing,
15	 * non-deleted owner's.
16	 *
17	 * <p>Duplicate detection is now this one key: an owner sharing another's surname and postcode but
18	 * with a different telephone has a different key and is no longer a hard household duplicate — it is
19	 * created and flagged a soft match by {@link AssignPossibleDuplicate}. Soft-deleted owners never
20	 * block a create.
21	 */
22	public class RequireUniqueIdentity {
23	
24	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
25	            throws DuplicateIdentityException {
26	        String identityKey = OwnerIdentityKey.forRequest(request);
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (existing.isDeleted()) {
29	                continue; // a soft-deleted owner never blocks a create
30	            }
31	            if (identityKey.equals(OwnerIdentityKey.forOwner(existing))) {
32	                throw new DuplicateIdentityException(identityKey);
33	            }
34	        }
35	    }
36	}
