21	public class AssignHouseholdId {
22	
23	    public void service(@Val OwnerFieldsDto request, @Val Owner owner) {
24	        owner.setHouseholdId(forRequest(request));
25	    }
26	
27	    /**
28	     * The householdId a create request maps to: the deterministic id for its {@code lastName} and
29	     * {@code postcode}, or {@code null} when no postcode is supplied (no household).
30	     */
31	    static String forRequest(OwnerFieldsDto request) {
32	        String postcode = request.getPostcode();
33	        if (postcode == null || postcode.isBlank()) {
