45	    /** Trim, collapse internal whitespace runs to a single space, and lower-case for comparison. */
46	    private static String normalize(String value) {
47	        if (value == null) {
48	            return "";
49	        }
50	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
51	    }
52	
53	    private static String sha256Hex(String value) {
54	        try {
55	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
