 *
 * <p>{@code customerCode} carries the owner's <em>current primary identifier</em>. Today that is the
 * {@link Owner#getCustomerCode() customerCode}; when the customerCode is later unified into a
 * {@code memberId}, only {@link #forOwner(long, Owner)} changes so the same field carries the
 * memberId instead — the event's shape and the way callers read the identifier stay the same.
 *
 * <p>Instances are immutable: fields are captured at construction and never mutated, so a recorded
 * event cannot be altered after the fact.
 */
public record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
        Integer membershipLevel) {

    /** Event marker carried in the {@code event} field. */
    public static final String EVENT = "OWNER_CREATED";

    /**
     * Builds the event for a persisted owner, reading its current primary identifier. This single
     * line is the switch point: replace {@code owner.getCustomerCode()} with the memberId once the
     * identifiers are unified and every emitted event follows.
     */
    public static OwnerCreatedEvent forOwner(long seq, Owner owner) {
        return new OwnerCreatedEvent(seq, owner.getId(), owner.getCustomerCode(),
                owner.getMembershipLevel());
    }

    /** Canonical JSON rendering of this event. */
    public String toJson() {
        StringBuilder json = new StringBuilder(96);
        json.append("{\"seq\":").append(this.seq)
                .append(",\"ownerId\":").append(this.ownerId)
                .append(",\"customerCode\":").append(quote(this.customerCode))
                .append(",\"membershipLevel\":").append(this.membershipLevel)
                .append(",\"event\":").append(quote(EVENT))
                .append('}');
        return json.toString();
    }

    private static String quote(String value) {
        if (value == null) {
            return "null";
        }
        StringBuilder out = new StringBuilder(value.length() + 2);
        out.append('"');
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            switch (c) {
                case '"' -> out.append("\\\"");
                case '\\' -> out.append("\\\\");
                case '\n' -> out.append("\\n");
                case '\r' -> out.append("\\r");
                case '\t' -> out.append("\\t");
                default -> {
                    if (c < 0x20) {
                        out.append(String.format("\\u%04x", (int) c));
                    }
                    else {
                        out.append(c);
                    }
                }
            }
        }
        out.append('"');
        return out.toString();
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Immutable structured audit event emitted alongside the human-readable audit line when an owner is
 * created. Rendered as the JSON object
 * {@code {seq, ownerId, memberId, membershipLevel, event:"OWNER_CREATED"}}.
 *
 * <p>{@code memberId} carries the owner's primary identifier, the unified
 * {@link Owner#getMemberId() memberId}.
 *
 * <p>Instances are immutable: fields are captured at construction and never mutated, so a recorded
 * event cannot be altered after the fact.
 */
public record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
        Integer membershipLevel) {

    /** Event marker carried in the {@code event} field. */
    public static final String EVENT = "OWNER_CREATED";

    /** Builds the event for a persisted owner, reading its unified {@code memberId} identifier. */
    public static OwnerCreatedEvent forOwner(long seq, Owner owner) {
        return new OwnerCreatedEvent(seq, owner.getId(), owner.getMemberId(),
                owner.getMembershipLevel());
    }

    /** Canonical JSON rendering of this event. */
    public String toJson() {
        StringBuilder json = new StringBuilder(96);
        json.append("{\"seq\":").append(this.seq)
                .append(",\"ownerId\":").append(this.ownerId)
                .append(",\"customerCode\":").append(quote(this.customerCode))
                .append(",\"membershipLevel\":").append(this.membershipLevel)
                .append(",\"event\":").append(quote(EVENT))
                .append('}');
        return json.toString();
    }

    private static String quote(String value) {
        if (value == null) {
            return "null";
        }
        StringBuilder out = new StringBuilder(value.length() + 2);
        out.append('"');
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            switch (c) {
                case '"' -> out.append("\\\"");
                case '\\' -> out.append("\\\\");
                case '\n' -> out.append("\\n");
                case '\r' -> out.append("\\r");
                case '\t' -> out.append("\\t");
                default -> {
                    if (c < 0x20) {
                        out.append(String.format("\\u%04x", (int) c));
                    }
                    else {
                        out.append(c);
                    }
                }
            }
        }
        out.append('"');
        return out.toString();
    }
}

package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "displayName",
        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials",
        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
    @Mapping(target = "membershipNumber",
        expression = "java(owner.getCustomerCode() + \"-M\" "
            + "+ org.springframework.samples.petclinic.rest.function.owner."
            + "FiscalYear.twoDigit(owner.getRegistrationDate()))")
    @Mapping(target = "fiscalYear",
        expression = "java(org.springframework.samples.petclinic.rest.function.owner."
            + "FiscalYear.forOwner(owner))")
    @Mapping(target = "locality",
        expression = "java(org.springframework.samples.petclinic.rest.function.owner."
            + "OwnerLocality.forOwner(owner))")
    @Mapping(target = "timezone",
        expression = "java(org.springframework.samples.petclinic.rest.function.owner."
            + "OwnerLocality.timezoneForOwner(owner))")
    @Mapping(target = "ownerSegment",
        expression = "java(org.springframework.samples.petclinic.rest.dto.OwnerDto."
            + "OwnerSegmentEnum.fromValue(org.springframework.samples.petclinic.rest.function."
            + "owner.OwnerSegment.forOwner(owner)))")
    @Mapping(target = "identityKey",
        expression = "java(org.springframework.samples.petclinic.rest.function.owner."
            + "OwnerIdentityKey.forOwner(owner))")
    @Mapping(target = "telephoneDisplay",
        expression = "java(org.springframework.samples.petclinic.rest.function.owner."
            + "TelephoneDisplay.forOwner(owner))")
    @Mapping(target = "selfLink",
        expression = "java(\"/api/owners/\" + owner.getId())")
    OwnerDto toOwnerDto(Owner owner);

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;
import java.time.Month;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Fiscal-year arithmetic for owner date-derived values. The fiscal year starts on 1 July and is
 * named by the calendar year in which it ends (1 July 2025 to 30 June 2026 is {@code FY26}), so a
 * date in July to December belongs to the following calendar year's fiscal year.
 *
 * <p>Used for the {@code fiscalYear} field, the membership number's year segment and the
 * fiscal-year tenure count, so every fiscal-year-derived value stays consistent.
 */
public final class FiscalYear {

    private FiscalYear() {
    }

    /** First month of the fiscal year. */
    public static final Month START = Month.JULY;

    /** The calendar year in which the fiscal year containing {@code date} ends. */
    public static int endingYear(LocalDate date) {
        return date.getMonthValue() >= START.getValue() ? date.getYear() + 1 : date.getYear();
    }

    /** The last two digits of the fiscal year, zero-padded (e.g. {@code "26"}). */
    public static String twoDigit(LocalDate date) {
        return String.format("%02d", Math.floorMod(endingYear(date), 100));
    }

    /** The fiscal year label, {@code 'FY<YY>'} (e.g. {@code "FY26"}). */
    public static String label(LocalDate date) {
        return "FY" + twoDigit(date);
    }

    /** Whole fiscal years elapsed from {@code from} to {@code to} (0 when both fall in one fiscal year). */
    public static int elapsed(LocalDate from, LocalDate to) {
        return endingYear(to) - endingYear(from);
    }

    /** The owner's fiscal year, derived from its (business-day-adjusted) registration date. */
    public static String forOwner(Owner owner) {
        return label(owner.getRegistrationDate());
    }
}

